mapper.select:
SELECT TOP (#{limit})
    /* 交换记录内部主键 */
    id,
    /* 贯穿调用链的请求编号 */
    request_id,
    /* 接口交易代码 */
    interface_code,
    /* 平台统一机构代码 */
    organization_code,
    /* 不含医疗正文的来源业务记录标识 */
    source_record_id,
    /* 调用方系统代码，对外映射为callerSystemCode */
    source_system_code AS caller_system_code,
    /* 目标系统代码 */
    target_system_code,
    /* 最终交换事实，对外映射为result */
    exchange_result AS result,
    /* 目标系统原始结果代码 */
    result_code AS target_result_code,
    /* 不含敏感正文的结果说明 */
    result_message,
    /* 调用处理耗时，单位毫秒 */
    duration_ms,
    /* 已脱敏且不含完整报文的请求摘要 */
    request_summary,
    /* 不含凭证和内部地址的通信错误摘要 */
    communication_error_summary,
    /* 平台接收请求的UTC时间 */
    received_at,
    /* 平台完成处理的UTC时间 */
    processed_at
FROM exch_exchange_record

WHERE organization_code = #{organizationCode}


    AND received_at >= #{receivedFrom}



    AND received_at <= #{receivedTo}



    AND interface_code = #{interfaceCode}



    AND source_record_id = #{sourceRecordId}



    AND request_id = #{requestId}



    AND exchange_result = #{result}


ORDER BY received_at DESC, id DESC
